// Quell — "AI on websites", the page-level part (0.7.4).
// Registered by the background only while the group is on, the user has asked
// for all-sites access and the browser still holds it. It hides AI buttons,
// panels and chat launchers on pages, from rules generated by
// pipeline/build_ai_web.py (rules/ai-web-cosmetic.json). The background hands
// each page only its own host's rules; nothing about the page is sent anywhere.
//
// Every rule's "hide" field already names the container to hide, so no empty
// frame is left; whatever a hidden thing still leaves empty above it is
// collapsed by the empty-ancestor logic below, and everything goes in the
// popup's list with Peek and Undo (QuellSettings.hidden). Hiding is cosmetic
// only: no page content is removed, and a page's own navigation, search and
// cart are never targets.

(async () => {
  if (window.__quellAiWeb) return;
  window.__quellAiWeb = true;
  const S = globalThis.QuellSettings;
  const DEFAULTS = { enabled: true, aiWebOn: true, aiWebAccess: true, aiWebAllowlist: [] };
  const STYLE_ID = 'quell-aiweb';
  const MARK = 'data-quell-aiweb';
  let rules = [];
  let observer = null;
  let active = false;
  let scheduled = false;

  const dropStyle = () => { const st = document.getElementById(STYLE_ID); if (st) st.remove(); };
  function addStyle() {
    dropStyle();
    const sels = rules.flatMap((r) => r.sel);
    if (!sels.length) return;
    const root = document.head || document.documentElement;
    if (!root) { setTimeout(addStyle, 0); return; }
    const st = document.createElement('style');
    st.id = STYLE_ID;
    st.textContent = sels.join(',\n') + ' { display: none !important; }';
    root.appendChild(st);
  }

  // What a hidden thing leaves empty goes with it (QuellSettings.emptied: the
  // highest ancestor with nothing visible left, never a landmark such as a nav,
  // header or article, never one that still holds other content). A separator
  // that sat beside it ("or", a bar, a slash) goes too, so none is left dangling.
  const SEP = /^(or|and|\||\/|·|•|-|–|—)$/i;
  const OWNER = 'aiweb';
  function hideSeparator(el, what) {
    const E = S.emptied;
    for (const dir of ['previous', 'next']) {
      let sib = el[dir + 'Sibling'];
      while (sib && sib.nodeType === 3 && !sib.nodeValue.trim()) sib = sib[dir + 'Sibling'];
      if (!sib) continue;
      if (sib.nodeType === 3 && SEP.test(sib.nodeValue.trim())) {
        const span = document.createElement('span');
        sib.parentNode.replaceChild(span, sib);
        span.appendChild(sib);
        E.collapse(span, what, OWNER);
      } else if (sib.nodeType === 1 && !sib.matches('input, button, a, select, textarea') && !sib.querySelector('input, button, a, select, textarea, img, svg')
        && SEP.test((sib.textContent || '').trim())) {
        E.collapse(sib, what, OWNER);
      }
    }
  }

  function sweep() {
    let n = 0;
    S.emptied.recheckCollapsed(OWNER, (el) => el.hasAttribute(MARK));
    for (const r of rules) {
      let found = [];
      try { found = document.querySelectorAll(r.sel.join(',')); } catch (_) { continue; }
      for (const el of found) {
        if (el.getAttribute(MARK) !== null) continue;
        el.setAttribute(MARK, r.what);
        n++;
        hideSeparator(el, r.what);
        const w = S.emptied.emptyAncestor(el);
        if (w) S.emptied.collapse(w, r.what, OWNER);
      }
    }
    if (n > 0) { try { chrome.runtime.sendMessage({ type: 'blocked', count: n }); } catch (_) { /* sw asleep */ } }
  }
  const schedule = () => {
    if (scheduled) return;
    scheduled = true;
    setTimeout(() => { scheduled = false; if (observer) sweep(); }, 300);
  };

  async function start() {
    if (active) return;
    active = true;
    try {
      const r = await chrome.runtime.sendMessage({ type: 'aiWebRules' });
      rules = (r && r.rules) || [];
    } catch (_) { rules = []; }
    if (!active || !rules.length) return;
    addStyle();
    const attach = () => {
      if (!active || observer) return;
      sweep();
      observer = new MutationObserver(schedule);
      observer.observe(document.documentElement, { childList: true, subtree: true });
    };
    if (document.body) attach(); else document.addEventListener('DOMContentLoaded', attach, { once: true });
  }
  function stop() {
    active = false;
    rules = [];
    if (observer) { observer.disconnect(); observer = null; }
    dropStyle();
    S.emptied.uncollapseAll(OWNER);
    for (const el of document.querySelectorAll('[' + MARK + ']')) el.removeAttribute(MARK);
  }
  const apply = (s) => {
    const paused = (s.aiWebAllowlist || []).includes(location.hostname);
    if (s.enabled && s.aiWebOn && s.aiWebAccess && !paused) start(); else stop();
  };

  try {
    // Listed by the popup, Peek and Undo (see QuellSettings.hidden).
    S.hidden.register('ai-web', () => {
      if (!active) return [];
      const out = [];
      for (const el of document.querySelectorAll('[' + MARK + ']')) {
        out.push({ el, label: el.getAttribute(MARK) || 'AI feature', detail: 'Hidden on this page' });
      }
      for (const el of document.querySelectorAll('[data-quell-collapsed="1"][data-quell-owner="aiweb"]')) {
        out.push({ el, label: el.dataset.quellLabel || 'AI feature', detail: 'Hidden on this page' });
      }
      return out;
    }, () => active);
    S.hidden.listen();
    S.onChange(['enabled', 'aiWebOn', 'aiWebAccess', 'aiWebAllowlist', 'aiWebButtons', 'aiWebChat', 'aiWebSupport'],
      () => { stop(); S.get(DEFAULTS).then(apply).catch(() => {}); });
    S.onGone(stop);
  } catch (_) { /* test context */ }

  let s = DEFAULTS;
  try { s = await S.get(DEFAULTS); } catch (_) { /* test context */ }
  apply(s);
})();
